package com.x.cloudnext.server.migration;

import java.io.InputStream;import java.security.MessageDigest;import java.util.ArrayList;import java.util.LinkedHashMap;import java.util.List;import java.util.Map;import java.util.Set;import java.util.stream.Collectors;
import org.springframework.core.io.Resource;import org.springframework.stereotype.Service;import org.springframework.util.StringUtils;
import com.fasterxml.jackson.databind.ObjectMapper;import com.x.cloudnext.server.audit.repository.AuditLogRepository;import com.x.cloudnext.server.drive.DriveItemType;import com.x.cloudnext.server.drive.DriveStorageService;import com.x.cloudnext.server.drive.entity.DriveItem;import com.x.cloudnext.server.drive.repository.DriveItemRepository;import com.x.cloudnext.server.drive.repository.DrivePublicLinkRepository;import com.x.cloudnext.server.drive.repository.DriveShareRepository;import com.x.cloudnext.server.workspace.repository.UserPreferenceRepository;import com.x.cloudnext.server.workspace.repository.WorkspaceMemberRepository;import com.x.cloudnext.server.workspace.repository.WorkspaceRepository;
import com.x.cloudnext.server.form.repository.PrincipalBindingRepository;import com.x.cloudnext.server.form.repository.UnitBindingRepository;import com.x.cloudnext.server.form.repository.IdentityBindingRepository;import com.x.cloudnext.server.form.repository.CanonicalAliasRepository;

@Service
public class MigrationInventoryService {
 @org.springframework.beans.factory.annotation.Autowired private com.x.cloudnext.server.drive.next.DriveStorageCleanupService storageCleanup;
 @org.springframework.beans.factory.annotation.Autowired private com.x.cloudnext.server.drive.next.DriveItemVersionRepository versions;
 private final DriveItemRepository items;private final DriveShareRepository shares;private final DrivePublicLinkRepository links;private final WorkspaceRepository workspaces;private final WorkspaceMemberRepository members;private final UserPreferenceRepository preferences;private final AuditLogRepository audit;private final DriveStorageService storage;private final ObjectMapper mapper;private final PrincipalBindingRepository principals;private final UnitBindingRepository units;private final IdentityBindingRepository identities;private final CanonicalAliasRepository aliases;
 public MigrationInventoryService(DriveItemRepository items,DriveShareRepository shares,DrivePublicLinkRepository links,WorkspaceRepository workspaces,WorkspaceMemberRepository members,UserPreferenceRepository preferences,AuditLogRepository audit,DriveStorageService storage,ObjectMapper mapper,PrincipalBindingRepository principals,UnitBindingRepository units,IdentityBindingRepository identities,CanonicalAliasRepository aliases){this.items=items;this.shares=shares;this.links=links;this.workspaces=workspaces;this.members=members;this.preferences=preferences;this.audit=audit;this.storage=storage;this.mapper=mapper;this.principals=principals;this.units=units;this.identities=identities;this.aliases=aliases;}
 public MigrationInventoryReport capture(){MigrationInventoryReport r=new MigrationInventoryReport();List<DriveItem> metadata=items.findAll();Set<String> metadataKeys=metadata.stream().filter(i->i.getItemType()==DriveItemType.FILE&&StringUtils.hasText(i.getStorageKey())).map(DriveItem::getStorageKey).collect(Collectors.toSet());long currentMetadataKeys=metadataKeys.size();versions.findAll().forEach(v->metadataKeys.add(v.storageKey));Set<String> physical=storage.supportsInventory()?storage.listStorageKeys():metadataKeys;List<String> missing=metadataKeys.stream().filter(k->!physical.contains(k)).sorted().collect(Collectors.toList());Set<String> pendingCleanup=storageCleanup.pendingKeys();List<String> orphan=physical.stream().filter(k->!metadataKeys.contains(k)&&!pendingCleanup.contains(k)).sorted().collect(Collectors.toList());Map<String,Long> counts=new LinkedHashMap<>();counts.put("fileAndFolderMetadata",(long)metadata.size());counts.put("fileMetadata",currentMetadataKeys);counts.put("fileVersions",versions.count());counts.put("storageObjects",(long)physical.size());counts.put("totalMetadataBytes",metadata.stream().filter(i->i.getItemType()==DriveItemType.FILE).mapToLong(i->i.getSizeBytes()==null?0L:i.getSizeBytes()).sum());counts.put("workspaces",workspaces.count());counts.put("workspaceMembers",members.count());counts.put("shares",shares.count());counts.put("publicLinks",links.count());counts.put("preferences",preferences.count());counts.put("auditLogs",audit.count());r.setCounts(counts);r.setMissingStorageKeys(missing);r.setOrphanStorageKeys(orphan);Map<String,String> hashes=new LinkedHashMap<>();physical.stream().sorted().limit(20).forEach(key->{try{Resource resource=storage.load(key);if(resource.exists())hashes.put(key,sha256(resource));}catch(Exception e){hashes.put(key,"UNREADABLE");}});r.setSampledSha256(hashes);r.setCriticalMetadataSha256(criticalMetadataSha256(metadata));return r;}
 public String json(MigrationInventoryReport report){try{return mapper.writeValueAsString(report);}catch(Exception e){throw new IllegalStateException("migration inventory cannot be serialized",e);}}
 public void assertMatches(String baselineJson){try{MigrationInventoryReport baseline=mapper.readValue(baselineJson,MigrationInventoryReport.class);MigrationInventoryReport current=capture();if(!baseline.getCounts().equals(current.getCounts())||!baseline.getSampledSha256().equals(current.getSampledSha256())||!baseline.getCriticalMetadataSha256().equals(current.getCriticalMetadataSha256())||!current.getMissingStorageKeys().isEmpty()||!current.getOrphanStorageKeys().isEmpty())throw new IllegalStateException("migration inventory differs from preview or has storage/metadata orphans");}catch(IllegalStateException e){throw e;}catch(Exception e){throw new IllegalStateException("stored migration inventory is invalid",e);}}
 private String sha256(Resource resource)throws Exception{MessageDigest digest=MessageDigest.getInstance("SHA-256");try(InputStream in=resource.getInputStream()){byte[] buffer=new byte[8192];int read;while((read=in.read(buffer))>=0)if(read>0)digest.update(buffer,0,read);}StringBuilder b=new StringBuilder();for(byte v:digest.digest())b.append(String.format("%02x",v));return b.toString();}
 private String criticalMetadataSha256(List<DriveItem> driveItems){try{List<String> rows=new ArrayList<>();driveItems.forEach(i->rows.add(row("ITEM",i.getId(),i.getParentId(),i.getName(),i.getFileType(),i.getContentType(),i.getOwnerPersonOaId(),i.getScopeType(),i.getScopeId(),i.getItemType(),i.getStorageKey(),i.getSizeBytes(),i.isDeleted(),i.getDeletedAt())));workspaces.findAll().forEach(w->rows.add(row("WORKSPACE",w.getId(),w.getName(),w.getStatus(),w.getRootItemId(),w.getCreatorPersonOaId())));members.findAll().forEach(m->rows.add(row("MEMBER",m.getId(),m.getWorkspaceId(),m.getPersonOaId(),m.getRole())));shares.findAll().forEach(s->rows.add(row("SHARE",s.getId(),s.getItemId(),s.getOwnerPersonOaId(),s.getTargetType(),s.getTargetId(),s.getPermission(),s.isRevoked(),s.getExpiresAt())));links.findAll().forEach(l->rows.add(row("LINK",l.getId(),l.getItemId(),l.getCreatorPersonOaId(),l.getPermission(),l.isRevoked(),l.getExpiresAt(),l.getDownloadLimit(),l.getDownloadCount())));preferences.findAll().forEach(p->rows.add(row("PREFERENCE",p.getId(),p.getPersonOaId(),p.getPreferenceKey(),p.getPreferenceValue())));audit.findAll().forEach(a->rows.add(row("AUDIT",a.getId(),a.getPersonOaId(),a.getAction(),a.getTargetType(),a.getTargetId(),a.getCreatedAt())));principals.findAll().forEach(p->rows.add(row("PRINCIPAL",p.getId(),p.getTenantId(),p.getFormEmployeeId(),p.getCanonicalPersonId(),p.getLegacyOaPersonId(),p.getMigrationDecision(),p.getStatus(),p.isAccountEnabled(),p.getAuthVersion())));units.findAll().forEach(u->rows.add(row("UNIT_BINDING",u.getId(),u.getTenantId(),u.getFormOrgId(),u.getCanonicalUnitId(),u.getLegacyOaUnitId(),u.getParentCanonicalUnitId(),u.getMigrationDecision(),u.getStatus())));identities.findAll().forEach(i->rows.add(row("IDENTITY_BINDING",i.getId(),i.getTenantId(),i.getFormAssignmentId(),i.getCanonicalIdentityId(),i.getCanonicalPersonId(),i.getCanonicalUnitId(),i.getMigrationDecision(),i.getStatus())));aliases.findAll().forEach(a->rows.add(row("ALIAS",a.getId(),a.getSubjectType(),a.getAliasKey(),a.getCanonicalKey(),a.getRelationType())));versions.findAll().forEach(v->rows.add(row("FILE_VERSION",v.id,v.itemId,v.versionNumber,v.storageKey,v.sha256)));java.util.Collections.sort(rows);MessageDigest digest=MessageDigest.getInstance("SHA-256");for(String row:rows){digest.update(row.getBytes(java.nio.charset.StandardCharsets.UTF_8));digest.update((byte)'\n');}return hex(digest.digest());}catch(Exception e){throw new IllegalStateException("critical migration metadata cannot be hashed",e);}}
 private String row(Object...values){StringBuilder b=new StringBuilder();for(Object value:values){String v=String.valueOf(value);b.append(v.length()).append(':').append(v).append('|');}return b.toString();}
 private String hex(byte[] value){StringBuilder b=new StringBuilder();for(byte v:value)b.append(String.format("%02x",v));return b.toString();}
}
